content:
{
  "concepts": [
    {
      "name": "代数封闭",
      "aliases": ["代数封闭的", "代数封闭域"],
      "boundary": "若一个域内任何非平凡多项式方程都有解，则该域是代数封闭的",
      "domain": "代数学"
    },
    {
      "name": "反证法",
      "aliases": ["反证法"],
      "boundary": "一种证明方法，假设命题不成立，推出矛盾，从而证明原命题成立",
      "domain": "逻辑学"
    },
    {
      "name": "Dedekind分割",
      "aliases": ["Dedekind分割"],
      "boundary": "有理数集的一个划分(A,B)，满足A、B非空，A∪B=Q，A∩B=∅，且对任意a∈A,b∈B有a<b，且A无最大元",
      "domain": "实数构造"
    },
    {
      "name": "第一次数学危机",
      "aliases": [],
      "boundary": "古希腊因发现√2不是有理数而引发的数学基础危机",
      "domain": "数学史"
    },
    {
      "name": "实数",
      "aliases": ["实数"],
      "boundary": "有理数和无理数的统称，可以用数轴上的点表示",
      "domain": "实数分析"
    },
    {
      "name": "有理数",
      "aliases": ["有理数", "有理数集Q", "Q"],
      "boundary": "可以表示为a/b的分数，其中a,b是整数且b≠0",
      "domain": "数论"
    },
    {
      "name": "整数",
      "aliases": ["整数", "整数集Z", "Z", "ℤ"],
      "boundary": "包括正整数、0、负整数的集合",
      "domain": "数论"
    },
    {
      "name": "加法封闭",
      "aliases": ["在加法下封闭", "加法封闭的"],
      "boundary": "集合中任意两元素的和仍在集合内",
      "domain": "代数学"
    },
    {
      "name": "减法封闭",
      "aliases": ["对减法封闭（或不封闭）"],
      "boundary": "集合中任意两元素的差仍在集合内",
      "domain": "代数学"
    },
    {
      "name": "乘法封闭",
      "aliases": ["在乘法下封闭", "乘法封闭的"],
      "boundary": "集合中任意两元素的积仍在集合内",
      "domain": "代数学"
    },
    {
      "name": "除法封闭",
      "aliases": ["除法不封闭"],
      "boundary": "集合中任意两元素（除数非零）的商仍在集合内",
      "domain": "代数学"
    },
    {
      "name": "完备性",
      "aliases": ["完备", "完备的", "Cauchy列必收敛"],
      "boundary": "度量空间中的每一个Cauchy列都收敛于该空间中的一点",
      "domain": "实分析"
    },
    {
      "name": "代数基本定理",
      "aliases": [],
      "boundary": "任何n次复系数多项式在C中恰好有n个根（计重数）",
      "domain": "复分析"
    },
    {
      "name": "欧拉公式",
      "aliases": ["欧拉恒等式"],
      "boundary": "e^(iθ) = cosθ + i sinθ",
      "domain": "复分析"
    },
    {
      "name": "复数",
      "aliases": ["复数", "复数集C", "C", "复数集合C"],
      "boundary": "形如a+bi的数，其中a,b∈R，i^2=-1",
      "domain": "复分析"
    },
    {
      "name": "自然数",
      "aliases": ["自然数", "自然数集N", "N", "ℕ"],
      "boundary": "集合{0,1,2,3,...}",
      "domain": "数论"
    },
    {
      "name": "数学归纳法",
      "aliases": [],
      "boundary": "一种证明方法：若性质对0成立，且由对n成立可推出对后继成立，则对所有自然数成立",
      "domain": "逻辑学"
    },
    {
      "name": "可数",
      "aliases": ["可数的"],
      "boundary": "集合与自然数集之间能建立一一对应",
      "domain": "集合论"
    },
    {
      "name": "无理数",
      "aliases": [],
      "boundary": "不能表示为有理数的实数",
      "domain": "实数分析"
    },
    {
      "name": "有序域",
      "aliases": ["有序的", "有序"],
      "boundary": "一个域且具有全序关系，且序与加法乘法兼容",
      "domain": "代数学"
    },
    {
      "name": "域",
      "aliases": [],
      "boundary": "一个代数结构，具有加法、乘法，且每个非零元有乘法逆元",
      "domain": "代数学"
    },
    {
      "name": "整环",
      "aliases": [],
      "boundary": "一个交换环且无零因子",
      "domain": "代数学"
    },
    {
      "name": "阿贝尔群",
      "aliases": [],
      "boundary": "满足交换律的群",
      "domain": "代数学"
    },
    {
      "name": "幺半群",
      "aliases": [],
      "boundary": "具有单位元的半群",
      "domain": "代数学"
    },
    {
      "name": "环",
      "aliases": ["交换环"],
      "boundary": "具有加法（构成阿贝尔群）和乘法（满足结合律）的代数结构",
      "domain": "代数学"
    },
    {
      "name": "等价类",
      "aliases": [],
      "boundary": "根据等价关系划分的集合中的一类",
      "domain": "集合论"
    },
    {
      "name": "Peano公理",
      "aliases": [],
      "boundary": "皮亚诺提出的自然数公理体系：0是自然数；每个自然数有后继；不同自然数后继不同；0不是任何数的后继；归纳法原理",
      "domain": "数学基础"
    },
    {
      "name": "Cantor枚举法",
      "aliases": ["Cantor蛇形对角线枚举"],
      "boundary": "一种列出所有有理数的方法",
      "domain": "集合论"
    },
    {
      "name": "Cantor对角线论证法",
      "aliases": [],
      "boundary": "一种证明实数不可数的方法：假设可数，构造对角线上的数证明矛盾",
      "domain": "集合论"
    },
    {
      "name": "数系扩张",
      "aliases": ["数系扩张链"],
      "boundary": "从自然数到整数、有理数、实数、复数的逐步扩展过程",
      "domain": "数学史"
    },
    {
      "name": "稠密性",
      "aliases": ["稠密", "处处稠密"],
      "boundary": "任意两个不同元素之间存在另一个元素",
      "domain": "实分析"
    },
    {
      "name": "上确界存在性",
      "aliases": [],
      "boundary": "有上界的非空子集必有上确界",
      "domain": "实分析"
    },
    {
      "name": "连通性",
      "aliases": [],
      "boundary": "拓扑空间不能分割为两个非空开集的不交并",
      "domain": "拓扑学"
    },
    {
      "name": "良序性",
      "aliases": [],
      "boundary": "任何非空子集有最小元",
      "domain": "序理论"
    },
    {
      "name": "后继",
      "aliases": ["后继函数", "后继操作"],
      "boundary": "自然数定义为S(n) = n+1",
      "domain": "数论"
    },
    {
      "name": "加法逆元",
      "aliases": [],
      "boundary": "对于元素a，存在元素b使得a+b=0",
      "domain": "代数学"
    },
    {
      "name": "乘法逆元",
      "aliases": [],
      "boundary": "对于非零元素a，存在元素b使得a×b=1",
      "domain": "代数学"
    },
    {
      "name": "von Neumann构造",
      "aliases": [],
      "boundary": "将自然数编码为集合：0=∅，1={0}，2={0,1}等",
      "domain": "集合论"
    }
  ]
}
